async function handle(req, parentSignal) {
  const deadline = performance.now() + req.budgetMs;   // one budget, at ingress
  const signal = AbortSignal.any([
    parentSignal, AbortSignal.timeout(deadline - performance.now())]);
  return fetch(backendUrl, { signal });   // forward the signal onward, not a fresh timeout
}
